begin;create extension if not exists pgtap with schema extensions;select no_plan();
insert into auth.users(instance_id,id,aud,role,email,encrypted_password,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at)values('00000000-0000-0000-0000-000000000000','f0000000-0000-0000-0000-000000000001','authenticated','authenticated','send-a@example.test','',now(),'{}','{}',now(),now()),('00000000-0000-0000-0000-000000000000','f0000000-0000-0000-0000-000000000002','authenticated','authenticated','send-b@example.test','',now(),'{}','{}',now(),now());
insert into public.organizations(id,public_id,name)values('f1000000-0000-0000-0000-000000000001','org_deliveryaaaaaaaa','Delivery A'),('f1000000-0000-0000-0000-000000000002','org_deliverybbbbbbbb','Delivery B');
insert into public.organization_memberships(id,organization_id,user_id,role,status)values('f2000000-0000-0000-0000-000000000001','f1000000-0000-0000-0000-000000000001','f0000000-0000-0000-0000-000000000001','owner','active'),('f2000000-0000-0000-0000-000000000002','f1000000-0000-0000-0000-000000000002','f0000000-0000-0000-0000-000000000002','owner','active');
insert into public.contacts(id,organization_id,created_by_membership_id,assigned_membership_id,first_name,last_name,primary_email,source,lifecycle_status,marketing_email_status)values('f3000000-0000-0000-0000-000000000001','f1000000-0000-0000-0000-000000000001','f2000000-0000-0000-0000-000000000001','f2000000-0000-0000-0000-000000000001','Ada','Eligible','Ada@Example.Test','Pack5','nurture','opted-in'),('f3000000-0000-0000-0000-000000000002','f1000000-0000-0000-0000-000000000001','f2000000-0000-0000-0000-000000000001','f2000000-0000-0000-0000-000000000001','Opal','Out','out@example.test','Pack5','nurture','opted-out'),('f3000000-0000-0000-0000-000000000003','f1000000-0000-0000-0000-000000000001','f2000000-0000-0000-0000-000000000001','f2000000-0000-0000-0000-000000000001','Sue','Suppressed','supp@example.test','Pack5','nurture','suppressed');

-- An ordinary consultant must not send to the owner's contacts.
insert into auth.users(instance_id,id,aud,role,email,encrypted_password,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at)values('00000000-0000-0000-0000-000000000000','f0000000-0000-0000-0000-000000000003','authenticated','authenticated','studio-member@example.test','',now(),'{}','{}',now(),now());
insert into public.organization_memberships(id,organization_id,user_id,role,status)values('f2000000-0000-0000-0000-000000000003','f1000000-0000-0000-0000-000000000001','f0000000-0000-0000-0000-000000000003','consultant','active');
insert into public.contacts(id,organization_id,created_by_membership_id,assigned_membership_id,first_name,last_name,primary_email,source,lifecycle_status,marketing_email_status)values('f3000000-0000-0000-0000-000000000004','f1000000-0000-0000-0000-000000000001','f2000000-0000-0000-0000-000000000003','f2000000-0000-0000-0000-000000000003','Visible','Person','visible@example.test','Pack5','nurture','opted-in');
insert into public.contact_lists(id,organization_id,created_by_membership_id,name)values('f4000000-0000-0000-0000-000000000001','f1000000-0000-0000-0000-000000000001','f2000000-0000-0000-0000-000000000001','Shared studio list');
insert into public.contact_list_memberships(organization_id,list_id,contact_id,added_by_membership_id)select organization_id,'f4000000-0000-0000-0000-000000000001',id,created_by_membership_id from public.contacts where organization_id='f1000000-0000-0000-0000-000000000001';
set local role authenticated;select set_config('request.jwt.claim.sub','f0000000-0000-0000-0000-000000000003',true);
insert into public.contact_segments(organization_id,created_by_membership_id,name,criteria)values('f1000000-0000-0000-0000-000000000001','f2000000-0000-0000-0000-000000000003','Studio segment','{"version":1,"combinator":"and","rules":[{"field":"source","operator":"is","value":"Pack5"}]}');
select is((select max(matching_count) from public.resolve_campaign_audience('list',(select public_id from public.contact_lists where name='Shared studio list'))),1::bigint,'list preview sees only authorized contact');
select is((select max(matching_count) from public.resolve_campaign_audience('segment',(select public_id from public.contact_segments where name='Studio segment'))),1::bigint,'segment preview sees only authorized contact');
insert into public.marketing_campaigns(organization_id,created_by_membership_id,name,subject,sender_name,reply_to,audience_type,audience_public_id,status,content)values('f1000000-0000-0000-0000-000000000001','f2000000-0000-0000-0000-000000000003','Authorized studio send','Hi','Alex','alex@example.test','list',(select public_id from public.contact_lists where name='Shared studio list'),'ready','{"version":1,"heading":"Hi","body":"Body","ctaLabel":"","ctaUrl":"","footer":"Footer"}');
select is((public.confirm_campaign_send((select public_id from public.marketing_campaigns where name='Authorized studio send'),'studio-auth-list-key',true)).eligible_count,1,'confirmation matches preview population under definer');
select is((select normalized_email from public.marketing_send_recipients),'visible@example.test','hidden owner contact never snapshotted');
select throws_ok($$update public.marketing_campaigns set subject='Changed'$$,'42501',null,'direct writes cannot bypass revision guard');
select throws_ok($$select public.save_marketing_campaign_draft('f1000000-0000-0000-0000-000000000001',(select public_id from public.marketing_campaigns),null,'{"status":"draft"}')$$,'42501',null,'sending content cannot change via RPC');
reset role;
select throws_ok($$update public.marketing_campaigns set subject='Changed' where name='Authorized studio send'$$,'42501',null,'history trigger protects privileged accidental content mutation');
update public.marketing_campaigns set status='sent' where name='Authorized studio send';
select throws_ok($$update public.marketing_campaigns set content='{}' where name='Authorized studio send'$$,'42501',null,'sent history immutable');
select throws_ok($$update public.marketing_campaigns set status='draft' where name='Authorized studio send'$$,'42501',null,'sent cannot revert to draft');
select is((select content->>'body' from public.marketing_send_runs),'Body','historical run content preserved');
set local role authenticated;
select set_config('request.jwt.claim.sub','f0000000-0000-0000-0000-000000000003',true);
create temporary table studio_payload as select '{"name":"V2 draft","description":"","subject":"Hi","preview_text":"Preheader","sender_name":"Alex","reply_to":"alex@example.test","audience_type":null,"audience_public_id":null,"content_version":2,"status":"draft","content":{"version":2,"type":"email","theme":{"fontFamily":"arial","fontSize":16,"textColor":"#172033","accentColor":"#2563EB"},"document":{"type":"doc","content":[{"type":"paragraph","attrs":{"textAlign":"left"}}]}}}'::jsonb p;
create temporary table studio_revision as select public_id,updated_at from public.save_marketing_campaign_draft('f1000000-0000-0000-0000-000000000001','',null,(select p from studio_payload));
select is((select content_version from public.marketing_campaigns where name='V2 draft'),2,'V2 persists locally');
select lives_ok($$select public.save_marketing_campaign_draft('f1000000-0000-0000-0000-000000000001',(select public_id from studio_revision),(select updated_at from studio_revision),(select p from studio_payload))$$,'matching revision can save');
select throws_ok($$select public.save_marketing_campaign_draft('f1000000-0000-0000-0000-000000000001',(select public_id from studio_revision),(select updated_at from studio_revision),(select p from studio_payload))$$,'40001',null,'second tab stale revision rejected atomically');
select throws_ok($$select public.save_marketing_campaign_draft('f1000000-0000-0000-0000-000000000001',(select public_id from studio_revision),null,(select p from studio_payload))$$,'40001',null,'missing revision rejected');
select throws_ok($$select public.save_marketing_campaign_draft('f1000000-0000-0000-0000-000000000001','',null,(select jsonb_set(p,'{status}','"ready"') from studio_payload))$$,'23514',null,'V2 Ready forbidden at database boundary');
select throws_ok($$select public.confirm_campaign_send((select public_id from studio_revision),'studio-v2-no-delivery',false)$$,'22023',null,'V2 external queue forbidden');
select throws_ok($$select public.save_marketing_campaign_draft('f1000000-0000-0000-0000-000000000001','',null,(select jsonb_set(p,'{content,document,content}','[{"type":"rawHTML","html":"<script>alert(1)</script>"}]') from studio_payload))$$,'23514',null,'raw HTML rejected in direct RPC');
select throws_ok($$select public.save_marketing_campaign_draft('f1000000-0000-0000-0000-000000000001','',null,(select jsonb_set(p,'{content,theme,fontFamily}','"url(evil)"') from studio_payload))$$,'23514',null,'arbitrary font CSS rejected in SQL');
select throws_ok($$select public.save_marketing_campaign_draft('f1000000-0000-0000-0000-000000000001','',null,(select jsonb_set(p,'{content,document,content}','[{"type":"button","attrs":{"label":"X","href":"javascript:alert(1)","alignment":"left"}}]') from studio_payload))$$,'23514',null,'unsafe URL rejected in SQL');

select throws_ok($$select public.save_marketing_campaign_draft('f1000000-0000-0000-0000-000000000001','',null,(select jsonb_set(p,'{content,version}','3') from studio_payload))$$,'23514',null,'unsupported future version rejected without replacing original');
select throws_ok($$select public.save_marketing_campaign_draft('f1000000-0000-0000-0000-000000000001','',null,(select jsonb_set(p,'{content,document,content}','[{"type":"emailImage","attrs":{"assetId":null,"alt":"X","alignment":"left","width":100,"href":null,"src":"data:image/png,x"}}]') from studio_payload))$$,'23514',null,'image data URLs and unknown attributes rejected');
insert into public.marketing_campaigns(organization_id,created_by_membership_id,name,subject,sender_name,reply_to,audience_type,audience_public_id,status,content)values('f1000000-0000-0000-0000-000000000001','f2000000-0000-0000-0000-000000000003','Authorized segment send','Hi','Alex','alex@example.test','segment',(select public_id from public.contact_segments where name='Studio segment'),'ready','{"version":1,"heading":"Hi","body":"Body","ctaLabel":"","ctaUrl":"","footer":"Footer"}');
select is((public.confirm_campaign_send((select public_id from public.marketing_campaigns where name='Authorized segment send'),'studio-auth-segment-key',true)).eligible_count,1,'segment confirmation matches authorized preview');
select is((select count(*) from public.marketing_send_recipients where normalized_email<>'visible@example.test'),0::bigint,'both confirmation paths exclude hidden contacts');
reset role;update public.organization_memberships set status='suspended' where id='f2000000-0000-0000-0000-000000000003';set local role authenticated;
select throws_ok($$select public.save_marketing_campaign_draft('f1000000-0000-0000-0000-000000000001','',null,(select p from studio_payload))$$,'42501',null,'inactive membership cannot create drafts');
select set_config('request.jwt.claim.sub','f0000000-0000-0000-0000-000000000002',true);
select is((select count(*) from public.marketing_campaigns),0::bigint,'other tenant campaigns hidden');
select throws_ok($$select public.save_marketing_campaign_draft('f1000000-0000-0000-0000-000000000001',(select public_id from studio_revision),null,(select p from studio_payload))$$,'42501',null,'cross-tenant RPC write rejected');
select throws_ok($$select public.save_marketing_campaign_draft('f1000000-0000-0000-0000-000000000002',(select public_id from studio_revision),null,(select p from studio_payload))$$,'42501',null,'relabeling campaign tenant does not grant access');
select * from finish();rollback;
